import {
  ANTELOPE_IGNORE_PATTERNS,
  antelopePreset,
} from "@antelopejs/tooling-configs/oxc/lint";
import { defineConfig } from "oxlint";

/**
 * The Vue layer keeps its own ESLint setup until the front-end migration, and
 * the Codex protocol types are generated by
 * `sidecar/scripts/generate-codex-types.mjs`. A builder spec's body is a list
 * of cases, so the function-length ceiling does not apply to it, and a
 * stand-in for a database stream has to be thenable, because the stream it
 * replaces is awaited.
 */
export default defineConfig({
  extends: [antelopePreset({ importSorting: false })],
  ignorePatterns: [
    ...ANTELOPE_IGNORE_PATTERNS,
    "frontend-vue/**",
    "sidecar/src/providers/codex/protocol/**",
  ],
  options: {
    typeAware: true,
  },
  overrides: [
    {
      files: ["src/builder/test/**/*.ts"],
      rules: {
        "max-lines-per-function": "off",
        "unicorn/no-thenable": "off",
      },
    },
  ],
});
